from taf.sbts.oam.sc.rest.services.sec.auth_v1 import SecV1
from taf.sbts.oam.sc.rest.services.sm.sm_v1 import SmV1
from taf.sbts.oam.sc.rest.services.cm.cm_v1 import CmV1
from taf.sbts.oam.sc.rest.services.fm.fm_v1 import FmV1
from taf.sbts.oam.sc.rest.services.swm.swm_v1 import SwmV1
from taf.sbts.oam.sc.rest.services.topology.topology_v1 import TopologyV1
from taf.sbts.oam.sc.rest.schemas.sm.site_info_v1 import SiteInfoSMV1
from taf.sbts.oam.sc.rest.schemas.sm.unit_available_operations_v1 import UnitAvailableOperationsSMV1
from taf.sbts.oam.sc.rest.schemas.sm.unit_operation_result_v1 import UnitOperationResultSMV1
from taf.sbts.oam.sc.rest.schemas.sm.unit_operation_trigger_result_v1 import UnitTriggerOperationResultSMV1
from taf.sbts.oam.sc.rest.schemas.cm.staged_plan_info import StagedPlanInfoCMV1
from taf.sbts.oam.sc.rest.schemas.cm.staged_delta_plan_info import StagedDeltaPlanInfoCMV1
from taf.sbts.oam.sc.rest.schemas.cm.delta_plan_activation_info import DeltaPlanActivationInfoCMV1
from taf.sbts.oam.sc.rest.schemas.cm.load_plan_template_info import LoadPlanTemplateInfoCMV1
from taf.sbts.oam.sc.rest.schemas.cm.cm_editor_operation_info import CmEditorOperationInfoCMV1
from taf.sbts.oam.sc.rest.schemas.fm.alarm_info import AlarmInfoFMV1
from taf.sbts.oam.sc.rest.schemas.swm.software_info_v1 import SoftwareInfoSWMV1
from taf.sbts.oam.sc.rest.schemas.topology.topology_unit_info_v1 import TopologyUnitInfoTOPOLGYV1
from taf.sbts.oam.sc.rest.schemas.topology.topology_hw_object_v1 import HwObjectTOPOLGYV1
import ast
import os


class ASIR22R3(object):
    def __init__(self, con_details):
        self.sec = SecV1(con_details=con_details)
        access_token = self.sec.login(username=con_details.username,
                                      password=con_details.password,
                                      scope=con_details.scope)
        self.sm = SmV1(con_details=con_details, access_token=access_token)
        self.cm = CmV1(con_details=con_details, access_token=access_token)
        self.fm = FmV1(con_details=con_details, access_token=access_token)
        self.swm = SwmV1(con_details=con_details, access_token=access_token)
        self.topology = TopologyV1(con_details=con_details, access_token=access_token)

    def refresh_token(self, scope='write'):
        api_instances = [
            self.sm.sm_api_instance,
            self.cm.cm_api_instance,
            self.fm.fm_api_instance,
            self.swm.swm_api_instance,
            self.topology.topology_api_instance,
        ]
        access_token = self.sec.refresh(scope=scope)
        for api_instance in api_instances:
            api_instance.api_client.configuration.access_token = access_token

    def get_number_of_logged_in_users(self):
        logged_in_users_response = self.sec.get_number_of_logged_in_users()
        return str(logged_in_users_response["numberOfUsers"])

    def get_site_info(self):
        site_info_response = self.sm.get_site_info()
        return SiteInfoSMV1.from_object_dict(site_info_response)

    def upload_plan(self, scf_path):
        upload_plan_response = self.cm.upload_plan(scf_path)
        staged_plan = StagedPlanInfoCMV1.from_object_dict(upload_plan_response)
        return staged_plan

    def upload_plan_template(self, delta_plan_id, scf_path):
        upload_plan_template_response = self.cm.upload_plan_template(delta_plan_id, scf_path)
        staged_plan_template = LoadPlanTemplateInfoCMV1.from_object_dict(upload_plan_template_response)
        return staged_plan_template

    def get_staged_plans(self):
        staged_plans_list = self.cm.get_staged_plans()
        return list(map(StagedPlanInfoCMV1.from_object_dict, staged_plans_list))

    def delete_staged_plan(self, plan_id):
        return self.cm.delete_staged_plan(plan_id)

    def validate_plan(self, plan_id, timeout):
        return ast.literal_eval(self.cm.validate_plan(plan_id, timeout))

    def get_validation_results(self, plan_id=None, job_id=None):
        return ast.literal_eval(self.cm.get_validation_results(plan_id, job_id))

    def get_validation_errors(self, plan_id=None, job_id=None):
        return self.cm.get_validation_errors(plan_id, job_id)[0]

    def migrate_nidd(self, delta_plan_id, nidd_target_version, timeout):
        operation_result = self.cm.migrate_nidd(delta_plan_id, nidd_target_version, timeout)
        return CmEditorOperationInfoCMV1.from_object_dict(operation_result)

    def activate_plan(self, plan_id, timeout):
        return ast.literal_eval(self.cm.activate_plan(plan_id, timeout))

    def create_new_delta_plan(self, source_plan, source_plan_id, timeout):
        return self.cm.create_new_delta_plan(source_plan, source_plan_id, timeout)

    def get_staged_delta_plans(self):
        get_staged_delta_plans = self.cm.get_staged_delta_plans()
        return list(map(StagedDeltaPlanInfoCMV1.from_object_dict, get_staged_delta_plans))

    def delete_delta_plan(self, delta_plan_id):
        return self.cm.delete_delta_plan(delta_plan_id)

    def update_parameter_of_delta_plan(self, delta_plan_id, operation, dn, name, field, index, value):
        return self.cm.update_parameter_of_delta_plan(delta_plan_id, operation, dn, name, field, index, value)

    def update_object_of_delta_plan(self, delta_plan_id, body):
        return self.cm.update_object_of_delta_plan(delta_plan_id, body)

    def activate_delta_plan(self, delta_plan_id, timeout):
        delta_plan_activation_response = self.cm.activate_delta_plan(delta_plan_id, timeout)
        return DeltaPlanActivationInfoCMV1.from_object_dict(delta_plan_activation_response)

    def reset_configuration(self):
        return self.sm.reset_configuration()

    def get_active_alarms(self):
        active_alarms_list = self.fm.get_active_alarms()
        return list(map(AlarmInfoFMV1.from_object_dict, active_alarms_list))

    def get_cleared_alarms(self):
        cleared_alarms_list = self.fm.get_cleared_alarms()
        return list(map(AlarmInfoFMV1.from_object_dict, cleared_alarms_list))

    def get_active_software_info(self):
        active_software_info = self.swm.get_active_software_info()
        return SoftwareInfoSWMV1.from_object_dict(active_software_info)

    def get_passive_software_info(self):
        passive_software_info = self.swm.get_passive_software_info()
        return list(map(SoftwareInfoSWMV1.from_object_dict, passive_software_info))

    def get_factory_software_info(self):
        factory_software_info = self.swm.get_factory_software_info()
        return SoftwareInfoSWMV1.from_object_dict(factory_software_info)

    def get_active_dist_names(self):
        return self.cm.get_active_dist_names()

    def get_unit_logical_info(self, uid):
        unit_logical_info = self.topology.get_unit_logical_info(uid=uid)
        return TopologyUnitInfoTOPOLGYV1.from_object_dict(unit_logical_info)

    def get_unit_physical_info(self, uid):
        unit_physical_info = self.topology.get_unit_physical_info(uid=uid)
        return TopologyUnitInfoTOPOLGYV1.from_object_dict(unit_physical_info)

    def get_unit_available_operations(self, uid):
        unit_available_operations = self.sm.get_unit_available_operations(uid=uid)
        return UnitAvailableOperationsSMV1.from_object_dict(unit_available_operations)

    def perform_operation_on_unit(self, uid, operation, timeout):
        operation_result = self.sm.perform_operation_on_unit(uid, operation, timeout)
        if timeout == 0:
            return UnitTriggerOperationResultSMV1.from_object_dict(operation_result)
        else:
            return UnitOperationResultSMV1.from_object_dict(operation_result)

    def get_site_logical_info(self):
        site_logical_info = self.topology.get_site_logical_info()
        return list(map(HwObjectTOPOLGYV1.from_object_dict, site_logical_info))

    def get_site_physical_info(self):
        site_physical_info = self.topology.get_site_physical_info()
        return list(map(HwObjectTOPOLGYV1.from_object_dict, site_physical_info))

    def get_active_scf_file(self, local_dir_path, timeout, file_name=None):
        plan_result = self.cm.get_active_plan_file(timeout)
        scf_name = file_name if file_name else plan_result['file_name']
        xml_result = plan_result['xml_result']
        return self.save_to_file(local_dir_path, scf_name, xml_result)

    @staticmethod
    def save_to_file(local_dir_path, file_name, xml_result):
        target_file_path = os.path.join(local_dir_path, file_name)
        with open(target_file_path, 'w') as f:
            f.write(xml_result)
        return target_file_path

    def get_all_software_packages(self):
        all_software_packages = self.swm.get_all_software_packages()
        return list(map(SoftwareInfoSWMV1.from_object_dict, all_software_packages))

    def get_delta_plan_file(self, delta_plan_id, content_type, local_dir_path, timeout, file_name=None):
        plan_result = self.cm.get_delta_plan_file(delta_plan_id, content_type, timeout)
        scf_name = file_name if file_name else plan_result['file_name']
        xml_result = plan_result['xml_result']
        return self.save_to_file(local_dir_path, scf_name, xml_result)
